@staticmethod
def _unstarted(code: SafeCode, *, unknown: bool = False) -> CodexExecutionResult:
    return CodexExecutionResult(version='codex-synthetic-execution-result-v1',
        outcome='unknown' if unknown else 'failed', answer='', output_state='none',
        usage=UsageSnapshot(input_tokens=None, output_tokens=None), error_code=code,
        consumed_provider_calls=0, first_response=None, first_response_sha256=None)

def run(self, peer: Callable[[CodexRequestGate], None] | None = None, *,
        before_request: Callable[[], None] | None = None) -> CodexExecutionResult:
    with self._lock:
        if self._started:
            if self._gate is None:
                return self._unstarted('CODEX_NEW_OUTBOUND_CONSENT_REQUIRED')
            self._gate.fail('CODEX_NEW_OUTBOUND_CONSENT_REQUIRED', replace=True)
            return self._gate.result()
        self._started = True
    try:
        summary = CodexFrozenOutboundSummary.model_validate(strict_json(canonical_bytes(self._summary)))
        profile = CodexRuntimeProfile.model_validate(strict_json(canonical_bytes(self._profile)))
        _checked_binding(self._prepared, summary, profile)
    except (ValueError, TypeError, KeyError, AttributeError, RecursionError):
        return self._unstarted('CODEX_BINDING_INVALID')
    if self._transport is None:
        return self._unstarted('CODEX_RUNTIME_UNAVAILABLE')
    try:
        gate = _Gate(self._prepared, summary, self._transport, self._clock, before_request)
        self._gate = gate
        gate.wall()
        if peer is None:
            gate.request(self._prepared.body, endpoint=self._prepared.endpoint,
                max_output_tokens=summary.budget.max_output_tokens)
        else:
            peer(gate)
        gate.wall()
    except ApiError as error:
        if self._gate is None:
            return self._unstarted('CODEX_OUTCOME_UNKNOWN', unknown=True)
        try:
            safe: SafeCode = TypeAdapter(SafeCode).validate_python(error.code)
        except ValueError:
            safe = 'CODEX_OUTCOME_UNKNOWN'
        self._gate.fail(safe, unknown=safe == 'CODEX_OUTCOME_UNKNOWN')
    except Exception:
        if self._gate is None:
            return self._unstarted('CODEX_OUTCOME_UNKNOWN', unknown=True)
        self._gate.fail('CODEX_OUTCOME_UNKNOWN', unknown=True)
    return self._gate.result()

class CodexTurnExecutor(Protocol):
    def available(self, profile: CodexRuntimeProfile) -> bool: ...

    def execute(self, prepared: PreparedCodexRequest, summary: CodexFrozenOutboundSummary,
                profile: CodexRuntimeProfile, before_request: Callable[[], None]) -> CodexExecutionResult: ...


@dataclass
class SyntheticCodexExecutor:
    """Explicit pure protocol test composition, never a host/CLI sandbox."""
    transport: SyntheticTransport
    peer: Callable[[CodexRequestGate], None] | None = None

    def available(self, profile: CodexRuntimeProfile) -> bool:
        return profile.version == 'codex-synthetic-runtime-profile-v1'

    def execute(self, prepared, summary, profile, before_request):
        return SyntheticCodexExecution(prepared,summary,profile,transport=self.transport).run(
            self.peer,before_request=before_request)


class CodexTurnWorker:
    def __init__(self, turns: CodexTurnService, provider: CodexConsentsService,
                 executor: CodexTurnExecutor | None = None):
        self.turns,self.provider,self.executor = turns,provider,executor
        self.database = turns.database
        self.owners = CodexExecutionOwners(self.database.settings.data_dir)
        self._stop = threading.Event()
        self._lock = threading.Lock()
        self._thread: threading.Thread | None = None
        self.last_error_code: str | None = None
        self._callback_context: tuple[str, str, str, int] | None = None
        self.imports: CodexArtifactImports | None = None
        self.controls = CodexBrokerControls(turns, provider, lambda: self._callback_context
            if type(self.executor) is SyntheticCodexExecutor else None)
        turns.broker_controls = self.controls

    def available(self, profile: CodexRuntimeProfile) -> bool:
        return self.executor is not None and self.executor.available(profile)
